<template><router-link :to="'/characters/'+character.id" class="card character-card tarot-card character-themed" :style="characterTheme(character)"><div class="tarot-image-frame" :class="{'tarot-image-frame--empty':!character.image||failed}" :style="{'--portrait-ink':portraitInk(character)}"><img v-if="character.image&&!failed" :src="character.image" :alt="character.name+'의 초상'" loading="lazy" @error="failed=true"/><span v-else class="tarot-color-placeholder" role="img" :aria-label="character.name+'의 초상화 없음'" :style="{background:portraitColor(character)}"></span><svg class="tarot-engraving" viewBox="0 0 300 410" preserveAspectRatio="none" fill="none" aria-hidden="true"><path d="M12 42V12h28M260 12h28v30M12 368v30h28m220 0h28v-30M20 55V20h35m190 0h35v35M20 355v35h35m190 0h35v-35" stroke="currentColor"/><path d="m150 6 7 10-7 10-7-10Zm0 378 7 10-7 10-7-10Z" fill="currentColor"/></svg><span class="tarot-affiliation"><CodexIcon :name="affiliationType(character)==='mage'?'quill':affiliationType(character)==='templar'?'seal':'book'"/>{{ affiliationLabel(character) }}</span></div><div class="tarot-caption"><p class="tarot-position">{{ character.position || '마탑의 일원' }}</p><h3 class="character-name">{{ character.name }}</h3><RecruitmentStatus :character="character"/><p class="tarot-owner">오너 · {{ owner }}</p></div></router-link></template>
<script setup>import {ref,watch} from 'vue';import {characterTheme,portraitColor,portraitInk} from './character-theme.mjs';import {affiliationType,affiliationLabel} from './affiliation.mjs';import CodexIcon from './CodexIcon.vue';import RecruitmentStatus from './RecruitmentStatus.vue';const props=defineProps({character:{type:Object,required:true},owner:String});const failed=ref(false);watch(()=>props.character.image,()=>failed.value=false);</script>
